//! Oracle vectors: mbstring's treatment of ill-formed UTF-8 in `mb_substr`, `mb_strlen`,
//! `mb_check_encoding`, `mb_str_split`, `mb_ord` and the case conversions, for every string of
//! up to four bytes over alphabets that cover each decoding decision, and for random strings.
//!
//! `tests/vectors/utf8.json` is generated by `tests/vectors/utf8.gen.php` in the PHP oracle
//! (`research/php-oracle`); its header describes the format. Regenerate from the repository
//! root with
//!
//! ```text
//! docker run --rm -i twig-oracle:3.31.1 php < crates/twig-unicode/tests/vectors/utf8.gen.php \
//!     > crates/twig-unicode/tests/vectors/utf8.json
//! ```

use std::collections::HashMap;

use serde::Deserialize;
use twig_unicode::{
    CaseMode, convert_case, mb_check_encoding, mb_ord, mb_str_split, mb_strlen, mb_substr,
};

#[derive(Deserialize)]
struct Vectors {
    php_version: String,
    exhaustive: Set,
    exhaustive4: Set,
    random: Set,
    corruptions: Corruptions,
}

#[derive(Deserialize)]
struct Corruptions {
    bases: Vec<String>,
    kinds: Vec<String>,
    check: String,
    strlen: Vec<usize>,
}

#[derive(Deserialize)]
struct Set {
    #[serde(default)]
    alphabet: Vec<u8>,
    #[serde(default)]
    lengths: Vec<usize>,
    #[serde(default)]
    inputs: Vec<String>,
    substr: Vec<String>,
    strlen: Vec<usize>,
    check: String,
    split: Vec<String>,
    ord: Vec<Option<i64>>,
    case: HashMap<String, HashMap<usize, String>>,
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// The inputs of a set, in the generator's order.
fn inputs(set: &Set) -> Vec<Vec<u8>> {
    if !set.inputs.is_empty() {
        return set.inputs.iter().map(|s| hex(s)).collect();
    }
    let mut all = Vec::new();
    for &len in &set.lengths {
        let mut strings = vec![Vec::new()];
        for _ in 0..len {
            strings = strings
                .iter()
                .flat_map(|prefix| {
                    set.alphabet.iter().map(move |&b| {
                        let mut s: Vec<u8> = prefix.clone();
                        s.push(b);
                        s
                    })
                })
                .collect();
        }
        all.extend(strings);
    }
    all
}

fn check_set(name: &str, set: &Set) {
    let inputs = inputs(set);
    assert_eq!(inputs.len(), set.substr.len(), "{name}");
    assert_eq!(inputs.len(), set.check.len(), "{name}");
    let modes = [
        ("upper", CaseMode::Upper),
        ("lower", CaseMode::Lower),
        ("title", CaseMode::Title),
        ("fold", CaseMode::Fold),
    ];
    for (i, s) in inputs.iter().enumerate() {
        let substr = hex(&set.substr[i]);
        assert_eq!(
            mb_substr(s, 0, None).unwrap(),
            substr,
            "{name} mb_substr {s:02X?}"
        );
        assert_eq!(mb_strlen(s), set.strlen[i], "{name} mb_strlen {s:02X?}");
        let valid = set.check.as_bytes()[i] == b'1';
        assert_eq!(
            mb_check_encoding(s),
            valid,
            "{name} mb_check_encoding {s:02X?}"
        );
        let pieces: String = mb_str_split(s, 1)
            .unwrap()
            .iter()
            .map(|p| p.len().to_string())
            .collect();
        assert_eq!(pieces, set.split[i], "{name} mb_str_split {s:02X?}");
        let ord = match mb_ord(s) {
            Err(_) => None,
            Ok(None) => Some(-1),
            Ok(Some(cp)) => Some(i64::from(cp)),
        };
        assert_eq!(ord, set.ord[i], "{name} mb_ord {s:02X?}");
        for (mode_name, mode) in modes {
            let want = set.case[mode_name]
                .get(&i)
                .map_or_else(|| substr.clone(), |h| hex(h));
            assert_eq!(convert_case(mode, s), want, "{name} {mode:?} {s:02X?}");
        }
    }
}

/// Rebuilds the "corruptions" inputs in the generator's order: base string, kind, offset.
fn corrupted_inputs(c: &Corruptions) -> Vec<Vec<u8>> {
    let mut all = Vec::new();
    for base in &c.bases {
        let b = hex(base);
        for kind in &c.kinds {
            for p in 0..=b.len() {
                let insert: &[u8] = match kind.as_str() {
                    "truncate" => {
                        all.push(b[..p].to_vec());
                        continue;
                    }
                    "replace_ff" => {
                        if p < b.len() {
                            all.push([&b[..p], b"\xFF", &b[p + 1..]].concat());
                        }
                        continue;
                    }
                    "insert_80" => b"\x80",
                    "insert_c0af" => b"\xC0\xAF",
                    "insert_surrogate" => b"\xED\xA0\x80",
                    "insert_f490" => b"\xF4\x90\x80\x80",
                    "insert_e282" => b"\xE2\x82",
                    other => panic!("unknown corruption kind {other}"),
                };
                all.push([&b[..p], insert, &b[p..]].concat());
            }
        }
    }
    all
}

#[test]
fn corrupted_long_strings_are_validated_like_php() {
    let vectors: Vectors = serde_json::from_str(include_str!("vectors/utf8.json")).unwrap();
    let c = &vectors.corruptions;
    let inputs = corrupted_inputs(c);
    assert_eq!(inputs.len(), c.check.len());
    assert_eq!(inputs.len(), c.strlen.len());
    for (i, s) in inputs.iter().enumerate() {
        let valid = c.check.as_bytes()[i] == b'1';
        assert_eq!(mb_check_encoding(s), valid, "mb_check_encoding {s:02X?}");
        assert_eq!(mb_strlen(s), c.strlen[i], "mb_strlen {s:02X?}");
    }
}

#[test]
fn ill_formed_utf8_is_handled_like_php() {
    let vectors: Vectors = serde_json::from_str(include_str!("vectors/utf8.json")).unwrap();
    assert_eq!(vectors.php_version, "8.5.13");
    check_set("exhaustive", &vectors.exhaustive);
    check_set("exhaustive4", &vectors.exhaustive4);
    check_set("random", &vectors.random);
}
